#!/usr/bin/env bash
set -e
echo "Making WelcomeBackScreen a real quick re-login feature..."
mkdir -p context screens

echo "  context/AuthContext.js"
mkdir -p "$(dirname 'context/AuthContext.js')"
echo '' | base64 --decode > 'context/AuthContext.js'

echo "  screens/ProfileScreen.js"
mkdir -p "$(dirname 'screens/ProfileScreen.js')"
echo '' | base64 --decode > 'screens/ProfileScreen.js'

echo "  screens/SplashScreen.js"
mkdir -p "$(dirname 'screens/SplashScreen.js')"
echo '' | base64 --decode > 'screens/SplashScreen.js'

echo "  screens/WelcomeBackScreen.js"
mkdir -p "$(dirname 'screens/WelcomeBackScreen.js')"
echo '' | base64 --decode > 'screens/WelcomeBackScreen.js'

echo "Done."
